import { createHash } from "node:crypto"
import { readdirSync, readFileSync, statSync } from "node:fs"
import { join, relative } from "node:path"

export function sha256(data: string | Uint8Array): string {
  return createHash("sha256").update(data).digest("hex")
}

export function sha256File(path: string): string {
  return sha256(readFileSync(path))
}

/** Canonical JSON: sorted keys, no whitespace — the same object always hashes the same. */
export function canonical(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`
  if (value && typeof value === "object") {
    const o = value as Record<string, unknown>
    return `{${Object.keys(o)
      .sort()
      .map((k) => `${JSON.stringify(k)}:${canonical(o[k])}`)
      .join(",")}}`
  }
  return JSON.stringify(value)
}

/** Every regular file under `dir`, relative and sorted, skipping the named directory basenames. */
export function listFiles(dir: string, exclude: string[] = ["node_modules"]): string[] {
  const out: string[] = []
  const walk = (d: string) => {
    for (const name of readdirSync(d).sort()) {
      if (exclude.includes(name)) continue
      const p = join(d, name)
      const st = statSync(p)
      if (st.isDirectory()) walk(p)
      else if (st.isFile()) out.push(relative(dir, p))
    }
  }
  walk(dir)
  return out
}

/** path → sha256 for the given relative files under root. */
export function manifestOf(root: string, files: string[]): Record<string, string> {
  const m: Record<string, string> = {}
  for (const f of files) m[f] = sha256File(join(root, f))
  return m
}
