export interface RunResult {
  code: number | null
  stdout: string
  stderr: string
  timedOut: boolean
  ms: number
}

const KEY_VARS = /(API_KEY|_TOKEN|SECRET|^ANTHROPIC|^OPENAI|^XAI|^CURSOR_|^ZAI|^ZHIPU|^MISTRAL|^OPENROUTER|^GEMINI|^GOOGLE_API)/i

/** The environment minus every provider credential (bench-refresh D14) and runner-private BENCH_/BOOPADA_ vars. */
export function scrubbedEnv(extra: Record<string, string> = {}): Record<string, string> {
  const env: Record<string, string> = {}
  for (const [k, v] of Object.entries(process.env)) {
    if (v !== undefined && !KEY_VARS.test(k) && !k.startsWith("BENCH_") && !k.startsWith("BOOPADA_")) env[k] = v
  }
  return { ...env, ...extra }
}

export async function run(cmd: string[], opts: { cwd: string; env?: Record<string, string>; timeoutMs: number; stdin?: string }): Promise<RunResult> {
  const started = Date.now()
  const proc = Bun.spawn(cmd, {
    cwd: opts.cwd,
    env: opts.env ?? scrubbedEnv(),
    stdin: opts.stdin === undefined ? "ignore" : new Blob([opts.stdin]),
    stdout: "pipe",
    stderr: "pipe",
  })
  let timedOut = false
  const timer = setTimeout(() => {
    timedOut = true
    proc.kill("SIGTERM")
    setTimeout(() => proc.kill("SIGKILL"), 15_000)
  }, opts.timeoutMs)
  const [stdout, stderr] = await Promise.all([new Response(proc.stdout).text(), new Response(proc.stderr).text()])
  const code = await proc.exited
  clearTimeout(timer)
  return { code, stdout, stderr, timedOut, ms: Date.now() - started }
}

export async function must(cmd: string[], opts: { cwd: string; env?: Record<string, string>; timeoutMs: number; stdin?: string }, what: string): Promise<RunResult> {
  const r = await run(cmd, opts)
  if (r.code !== 0 || r.timedOut) throw new Error(`${what} failed (exit ${r.code}${r.timedOut ? ", timed out" : ""}): ${(r.stderr || r.stdout).slice(-2000)}`)
  return r
}
