// The measurement path is PINNED, not trusted (self-improve D9 §2).
// PIN.json names every file the evaluator executes or reads by content hash,
// the workload commits by tree hash, and the tool versions. Every run
// re-verifies all of it and refuses on the first difference.
import { existsSync, readFileSync, writeFileSync } from "node:fs"
import { join } from "node:path"
import { canonical, listFiles, manifestOf, sha256 } from "./hash"
import {
  CHAIN_A,
  HANDOFF_BENCH,
  HIDDEN_TESTS,
  PIN_FILE,
  PINNED_RUNNER_FILES,
  REFERENCE_A,
  REFERENCE_A_REF,
  SANDBOX_EXEC,
  SCENARIO,
  SKELETON,
  SKELETON_REF,
} from "./paths"
import { run } from "./proc"

export interface Pin {
  version: 1
  created_at: string
  handoff_bench_commit: string
  /** Relative to SCENARIO → sha256. */
  files: Record<string, string>
  skeleton: { ref: string; commit: string; tree: string }
  reference_a: { ref: string; commit: string; tree: string }
  tools: Record<string, string>
}

export type PinProblem =
  | { kind: "modified" | "missing" | "added"; path: string }
  | { kind: "dirty"; path: string }
  | { kind: "tree"; path: string; expected: string; actual: string }
  | { kind: "tool"; path: string; expected: string; actual: string }
  | { kind: "error"; path: string; detail: string }

/** Identity of the pin: everything but when it was written. */
export function pinHash(pin: Pin): string {
  const { created_at: _at, ...rest } = pin
  return sha256(canonical(rest))
}

/** Compare two manifests. Pure; used on the real path and on tamper fixtures. */
export function diffManifest(expected: Record<string, string>, actual: Record<string, string>): PinProblem[] {
  const problems: PinProblem[] = []
  for (const path of Object.keys(expected).sort()) {
    if (!(path in actual)) problems.push({ kind: "missing", path })
    else if (actual[path] !== expected[path]) problems.push({ kind: "modified", path })
  }
  for (const path of Object.keys(actual).sort()) if (!(path in expected)) problems.push({ kind: "added", path })
  return problems
}

/** The pinned file set, enumerated the same way at pin time and at verify time (so additions show). */
export function pinnedFiles(): string[] {
  const files = listFiles(HIDDEN_TESTS).map((f) => join("hidden-tests", f))
  files.push("CHAIN-A.md")
  for (const f of PINNED_RUNNER_FILES) files.push(join("runner", f))
  return files.sort()
}

async function git(cwd: string, ...args: string[]): Promise<string> {
  const r = await run(["git", ...args], { cwd, timeoutMs: 60_000 })
  if (r.code !== 0) throw new Error(`git ${args.join(" ")} in ${cwd}: ${r.stderr.trim()}`)
  return r.stdout.trim()
}

async function commitAndTree(repo: string, ref: string): Promise<{ commit: string; tree: string }> {
  return { commit: await git(repo, "rev-parse", `${ref}^{commit}`), tree: await git(repo, "rev-parse", `${ref}^{tree}`) }
}

export async function toolVersions(): Promise<Record<string, string>> {
  const v = async (cmd: string[]) => {
    const r = await run(cmd, { cwd: "/", timeoutMs: 30_000 })
    return (r.stdout || r.stderr).trim().split("\n")[0] ?? ""
  }
  return {
    bun: await v(["bun", "--version"]),
    node: await v(["node", "--version"]),
    npm: await v(["npm", "--version"]),
    claude: await v(["claude", "--version"]),
    macos: await v(["sw_vers", "-productVersion"]),
    "sandbox-exec": existsSync(SANDBOX_EXEC) ? "present" : "missing",
  }
}

export async function buildPin(): Promise<Pin> {
  const files = pinnedFiles()
  const existing = files.filter((f) => existsSync(join(SCENARIO, f)))
  if (existing.length !== files.length) throw new Error(`pinned file missing: ${files.find((f) => !existing.includes(f))}`)
  return {
    version: 1,
    created_at: new Date().toISOString(),
    handoff_bench_commit: await git(HANDOFF_BENCH, "rev-parse", "HEAD"),
    files: manifestOf(SCENARIO, files),
    skeleton: { ref: SKELETON_REF, ...(await commitAndTree(SKELETON, SKELETON_REF)) },
    reference_a: { ref: REFERENCE_A_REF, ...(await commitAndTree(REFERENCE_A, REFERENCE_A_REF)) },
    tools: await toolVersions(),
  }
}

export function readPin(file: string = PIN_FILE): Pin {
  if (!existsSync(file)) throw new Error(`no pin at ${file}; run: evaluator pin write`)
  return JSON.parse(readFileSync(file, "utf8")) as Pin
}

export function writePin(pin: Pin, file: string = PIN_FILE): void {
  writeFileSync(file, `${JSON.stringify(pin, null, 2)}\n`)
}

/** Every way the current measurement path differs from the pin. Empty means the pin holds. */
export async function verifyPin(pin: Pin): Promise<PinProblem[]> {
  const problems: PinProblem[] = []
  const files = pinnedFiles()
  const present = files.filter((f) => existsSync(join(SCENARIO, f)))
  problems.push(...diffManifest(pin.files, manifestOf(SCENARIO, present)))
  // Uncommitted edits in a pinned path: content hashes already catch a changed
  // file, but a dirty path is also not reproducible from any commit.
  try {
    const dirty = await git(HANDOFF_BENCH, "status", "--porcelain", "--", ...Object.keys(pin.files).map((f) => join("scenario5-launch-bench", f)))
    for (const line of dirty.split("\n").filter(Boolean)) problems.push({ kind: "dirty", path: line.slice(3).trim() })
  } catch (err) {
    problems.push({ kind: "error", path: HANDOFF_BENCH, detail: String(err) })
  }
  for (const [name, repo, want] of [
    ["skeleton", SKELETON, pin.skeleton],
    ["reference_a", REFERENCE_A, pin.reference_a],
  ] as const) {
    try {
      const got = await commitAndTree(repo, want.ref)
      if (got.commit !== want.commit || got.tree !== want.tree) problems.push({ kind: "tree", path: `${name}@${want.ref}`, expected: want.tree, actual: got.tree })
    } catch (err) {
      problems.push({ kind: "error", path: `${name}@${want.ref}`, detail: String(err) })
    }
  }
  const tools = await toolVersions()
  for (const [k, want] of Object.entries(pin.tools)) {
    if (tools[k] !== want) problems.push({ kind: "tool", path: k, expected: want, actual: tools[k] ?? "" })
  }
  return problems
}

export function describeProblem(p: PinProblem): string {
  switch (p.kind) {
    case "modified":
    case "missing":
    case "added":
    case "dirty":
      return `${p.kind}: ${p.path}`
    case "tree":
    case "tool":
      return `${p.kind} ${p.path}: pinned ${p.expected}, found ${p.actual}`
    case "error":
      return `error ${p.path}: ${p.detail}`
  }
}

export { CHAIN_A }
