cat > lib/sandbox.ts <<'EOF'
// Kernel-enforced boundaries for candidate code (self-improve D9 §3, §4, §9).
// macOS Seatbelt via /usr/bin/sandbox-exec: deprecated by Apple, enforced today
// (verified 2026-09-16 on macOS 27.0), and the only enforcement this uid has
// without sudo. Everything below is tested, not assumed: `selfTest` runs the
// probes inside the real profile before any launch.
import { existsSync, mkdtempSync, unlinkSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { SANDBOX_EXEC } from "./paths"
import { run } from "./proc"

function q(path: string): string {
  if (/["\\\n]/.test(path)) throw new Error(`unsafe path for a sandbox profile: ${path}`)
  return `"${path}"`
}

const sub = (paths: string[]) => paths.map((p) => `(subpath ${q(p)})`).join(" ")

/**
 * The candidate's profile: writes only into the listed roots, no reads of the
 * sealed set, no launchctl. Applies to the agent, the candidate sofar, its
 * build, and everything they spawn.
 */
export function candidateProfile(o: { writable: string[]; unreadable: string[] }): string {
  return [
    "(version 1)",
    "(allow default)",
    "(deny file-write*)",
    `(allow file-write* ${sub(o.writable)})`,
    o.unreadable.length ? `(deny file-read* ${sub(o.unreadable)})` : ";; nothing sealed",
    `(deny process-exec (literal "/bin/launchctl"))`,
    "",
  ].join("\n")
}

/** The scoring profile: the agent-written app builds and runs with writes only into its repo, tmp and caches; reads are free because the hidden tests ARE the process. */
export function scoreProfile(o: { writable: string[] }): string {
  return ["(version 1)", "(allow default)", "(deny file-write*)", `(allow file-write* ${sub(o.writable)})`, `(deny process-exec (literal "/bin/launchctl"))`, ""].join("\n")
}

/** The evaluator's own profile: it can do anything except read the release holdout (D9 §9). */
export function evaluatorProfile(o: { unreadable: string[] }): string {
  return ["(version 1)", "(allow default)", `(deny file-read* ${sub(o.unreadable)})`, ""].join("\n")
}

export function sandboxed(profileFile: string, argv: string[]): string[] {
  return [SANDBOX_EXEC, "-f", profileFile, ...argv]
}

export interface Probe {
  name: string
  /** A /bin/sh command line. */
  cmd: string
  expect: "deny" | "allow"
  /** A file the probe would create; asserted absent (deny) or removed (allow) afterwards. */
  leaves?: string
}

export interface ProbeResult extends Probe {
  ok: boolean
  exit: number | null
  detail: string
}

export async function selfTest(profileFile: string, probes: Probe[]): Promise<ProbeResult[]> {
  const results: ProbeResult[] = []
  for (const p of probes) {
    const r = await run(sandboxed(profileFile, ["/bin/sh", "-c", p.cmd]), { cwd: "/", timeoutMs: 30_000 })
    const denied = r.code !== 0
    let ok = p.expect === "deny" ? denied : !denied
    let detail = (r.stderr || r.stdout).trim().split("\n")[0] ?? ""
    if (p.leaves) {
      const exists = existsSync(p.leaves)
      if (p.expect === "deny" && exists) {
        ok = false
        detail = `probe file exists: ${p.leaves}`
        try {
          unlinkSync(p.leaves)
        } catch {}
      }
      if (p.expect === "allow") {
        if (!exists) {
          ok = false
          detail = `probe file missing: ${p.leaves}`
        } else unlinkSync(p.leaves)
      }
    }
    results.push({ ...p, ok, exit: r.code, detail })
  }
  return results
}

/** The probes every run must pass before a launch (D9 §4). */
export function standardProbes(o: { hiddenTests: string; sealed: string; reference: string; results: string; evaluatorRepo: string; runnerLib: string; candidateDir?: string; cell: string }): Probe[] {
  const probes: Probe[] = [
    { name: "write hidden-tests", cmd: `echo x > ${o.hiddenTests}/.evaluator-probe`, expect: "deny", leaves: `${o.hiddenTests}/.evaluator-probe` },
    { name: "read hidden-tests/harness.ts", cmd: `cat ${o.hiddenTests}/harness.ts > /dev/null`, expect: "deny" },
    { name: "list hidden-tests", cmd: `ls ${o.hiddenTests} > /dev/null`, expect: "deny" },
    { name: "list bench-sealed", cmd: `ls ${o.sealed} > /dev/null`, expect: "deny" },
    { name: "read reference", cmd: `cat ${o.reference}/package.json > /dev/null`, expect: "deny" },
    { name: "write results", cmd: `echo x > ${o.results}/.evaluator-probe`, expect: "deny", leaves: `${o.results}/.evaluator-probe` },
    { name: "read results", cmd: `ls ${o.results} > /dev/null`, expect: "deny" },
    { name: "write evaluator repo", cmd: `echo x > ${o.evaluatorRepo}/.evaluator-probe`, expect: "deny", leaves: `${o.evaluatorRepo}/.evaluator-probe` },
    { name: "append runner paths.ts", cmd: `echo x >> ${o.runnerLib}/paths.ts`, expect: "deny" },
    { name: "exec launchctl", cmd: "launchctl list > /dev/null", expect: "deny" },
    { name: "write the cell", cmd: `echo x > ${o.cell}/.evaluator-probe`, expect: "allow", leaves: `${o.cell}/.evaluator-probe` },
  ]
  if (o.candidateDir) probes.push({ name: "write candidate install", cmd: `echo x > ${o.candidateDir}/.evaluator-probe`, expect: "deny", leaves: `${o.candidateDir}/.evaluator-probe` })
  return probes
}

export function writeProfile(dir: string, name: string, text: string): string {
  const file = join(dir, name)
  writeFileSync(file, text)
  return file
}

export function tempProfile(text: string): string {
  const dir = mkdtempSync(join(tmpdir(), "evaluator-sb-"))
  return writeProfile(dir, "profile.sb", text)
}
