// Every execution of candidate code passes through a shim that applies the
// sandbox (self-improve D9 §3). `claude` is reached through PATH by the pinned
// runner; the candidate `sofar` IS the bin entry of the prefix the runner is
// pointed at through BENCH_SOFAR_PREFIX.
import { chmodSync, mkdirSync, writeFileSync } from "node:fs"
import { join } from "node:path"
import { SANDBOX_EXEC } from "./paths"

export interface Shims {
  /** Prepend to PATH: holds `claude`. */
  binDir: string
  /** BENCH_SOFAR_PREFIX: <prefix>/node_modules/.bin/sofar is the sandboxed candidate. */
  prefixDir: string
  files: string[]
}

function shim(file: string, profile: string, target: string[]): void {
  const argv = target.map((a) => `"${a}"`).join(" ")
  writeFileSync(
    file,
    `#!/bin/sh\n# sofar-evaluator shim (self-improve D9): candidate code runs only inside the sandbox.\nexec "${SANDBOX_EXEC}" -f "${profile}" ${argv} "$@"\n`,
  )
  chmodSync(file, 0o755)
}

export function writeShims(dir: string, o: { profileFile: string; claudeBin: string; nodeBin: string; candidateCli: string }): Shims {
  const binDir = join(dir, "bin")
  const sofarBin = join(dir, "prefix", "node_modules", ".bin")
  mkdirSync(binDir, { recursive: true })
  mkdirSync(sofarBin, { recursive: true })
  const claude = join(binDir, "claude")
  const sofar = join(sofarBin, "sofar")
  shim(claude, o.profileFile, [o.claudeBin])
  shim(sofar, o.profileFile, [o.nodeBin, o.candidateCli])
  return { binDir, prefixDir: join(dir, "prefix"), files: [claude, sofar] }
}
