// Scores come from the trusted process and are cross-checked (self-improve D9 §7).
// The junit file is parsed for per-test names, then reconciled against the
// `bun test` exit code and its own summary; a filter that ran no tests is
// never a pass, and a disagreement is refused, not averaged.
import { existsSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { run, scrubbedEnv } from "./proc"
import { sandboxed } from "./sandbox"

export interface JunitParse {
  pass: number
  fail: number
  skipped: number
  failed: string[]
  /** file → { pass, fail } as the junit reports it. */
  byFile: Record<string, { pass: number; fail: number }>
  totals: { tests: number; failures: number; skipped: number } | null
}

export function parseJunit(xml: string): JunitParse {
  const out: JunitParse = { pass: 0, fail: 0, skipped: 0, failed: [], byFile: {}, totals: null }
  const root = /<testsuites\b([^>]*)>/.exec(xml)
  if (root) {
    const n = (k: string) => Number(new RegExp(`\\b${k}="(\\d+)"`).exec(root[1] ?? "")?.[1] ?? "0")
    out.totals = { tests: n("tests"), failures: n("failures"), skipped: n("skipped") }
  }
  for (const m of xml.matchAll(/<testcase\b([^>]*?)(\/>|>([\s\S]*?)<\/testcase>)/g)) {
    const attrs = m[1] ?? ""
    const name = /\bname="([^"]*)"/.exec(attrs)?.[1] ?? "?"
    const file = /\bfile="([^"]*)"/.exec(attrs)?.[1] ?? /\bclassname="([^"]*)"/.exec(attrs)?.[1] ?? ""
    const body = m[3] ?? ""
    const entry = (out.byFile[file] ??= { pass: 0, fail: 0 })
    if (/<failure|<error/.test(body)) {
      out.fail++
      entry.fail++
      out.failed.push(`${file} > ${name}`)
    } else if (/<skipped/.test(body)) out.skipped++
    else {
      out.pass++
      entry.pass++
    }
  }
  return out
}

/** bun's own summary lines (" 8 pass", " 1 fail", " 2 skip"). */
export function parseSummary(text: string): { pass: number; fail: number; skip: number } | null {
  const pass = /^\s*(\d+) pass$/m.exec(text)
  const fail = /^\s*(\d+) fail$/m.exec(text)
  if (!pass && !fail) return null
  const skip = /^\s*(\d+) skip$/m.exec(text)
  return { pass: Number(pass?.[1] ?? 0), fail: Number(fail?.[1] ?? 0), skip: Number(skip?.[1] ?? 0) }
}

export type Verdict =
  | { kind: "ok"; pass: number; fail: number; failed: string[]; bySession: Record<string, { pass: number; fail: number }> }
  | { kind: "no_tests_ran"; detail: string }
  | { kind: "score_inconsistent"; detail: string }

/** Per-session [redacted] a session's files are `s1.test.ts`, `s1.ui.test.ts`, … */
export function bySession(junit: JunitParse, sessions: string[]): Record<string, { pass: number; fail: number }> {
  const out: Record<string, { pass: number; fail: number }> = {}
  for (const s of sessions) {
    const prefix = `${s.toLowerCase()}.`
    const acc = { pass: 0, fail: 0 }
    for (const [file, c] of Object.entries(junit.byFile)) {
      if (file.split("/").pop()?.startsWith(prefix)) {
        acc.pass += c.pass
        acc.fail += c.fail
      }
    }
    out[s] = acc
  }
  return out
}

export function reconcile(junit: JunitParse | null, summary: { pass: number; fail: number; skip: number } | null, exitCode: number | null, sessions: string[]): Verdict {
  if (!junit || junit.pass + junit.fail === 0) return { kind: "no_tests_ran", detail: junit ? "junit holds no executed test" : "no junit file" }
  if (!summary) return { kind: "score_inconsistent", detail: "bun test printed no summary" }
  if (junit.pass !== summary.pass || junit.fail !== summary.fail) return { kind: "score_inconsistent", detail: `junit ${junit.pass}/${junit.fail} vs summary ${summary.pass}/${summary.fail} (pass/fail)` }
  if (junit.totals && junit.totals.tests !== junit.pass + junit.fail + junit.skipped) return { kind: "score_inconsistent", detail: `junit totals ${junit.totals.tests} vs cases ${junit.pass + junit.fail + junit.skipped}` }
  if ((exitCode === 0) !== (junit.fail === 0)) return { kind: "score_inconsistent", detail: `exit ${exitCode} with ${junit.fail} failures` }
  const per = bySession(junit, sessions)
  const empty = sessions.filter((s) => per[s]!.pass + per[s]!.fail === 0)
  if (empty.length) return { kind: "no_tests_ran", detail: `no test executed for ${empty.join(", ")}` }
  return { kind: "ok", pass: junit.pass, fail: junit.fail, failed: junit.failed, bySession: per }
}

export interface ScoreResult {
  build: "ok" | "failed"
  verdict: Verdict
  ms: number
}

/** Build the app under test and run the pinned hidden suites for `sessions`, all inside the score profile. */
export async function scoreRepo(o: { repo: string; sessions: string[]; hiddenTests: string; profileFile: string; logDir: string }): Promise<ScoreResult> {
  const started = Date.now()
  const env = scrubbedEnv({ NEXT_TELEMETRY_DISABLED: "1" })
  const install = await run(sandboxed(o.profileFile, ["bun", "install"]), { cwd: o.repo, env, timeoutMs: 600_000 })
  const build = install.code === 0 ? await run(sandboxed(o.profileFile, ["bun", "run", "build"]), { cwd: o.repo, env, timeoutMs: 900_000 }) : install
  writeFileSync(join(o.logDir, "build.log"), `${install.stdout}\n${install.stderr}\n${build.stdout}\n${build.stderr}`)
  if (build.code !== 0) return { build: "failed", verdict: { kind: "no_tests_ran", detail: "build failed" }, ms: Date.now() - started }
  const junitDir = mkdtempSync(join(tmpdir(), "evaluator-junit-"))
  const junit = join(junitDir, `${crypto.randomUUID()}.xml`)
  const filters = o.sessions.map((s) => s.toLowerCase())
  const tests = await run(sandboxed(o.profileFile, ["bun", "test", "--timeout", "120000", "--reporter=junit", `--reporter-outfile=${junit}`, ...filters]), {
    cwd: o.hiddenTests,
    env: { ...env, BENCH_APP_DIR: o.repo },
    timeoutMs: 1_800_000,
  })
  writeFileSync(join(o.logDir, "tests.log"), `${tests.stdout}\n${tests.stderr}`)
  const xml = existsSync(junit) ? readFileSync(junit, "utf8") : null
  if (xml) writeFileSync(join(o.logDir, "tests.xml"), xml)
  const verdict = reconcile(xml ? parseJunit(xml) : null, parseSummary(`${tests.stdout}\n${tests.stderr}`), tests.timedOut ? null : tests.code, o.sessions)
  return { build: "ok", verdict, ms: Date.now() - started }
}
