// Result capture: written only by the evaluator process, hashed beside itself.
import { appendFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { sha256 } from "./hash"

export function writeJson(file: string, value: unknown): string {
  mkdirSync(dirname(file), { recursive: true })
  const text = `${JSON.stringify(value, null, 2)}\n`
  writeFileSync(file, text)
  const hash = sha256(text)
  writeFileSync(`${file}.sha256`, `${hash}\n`)
  return hash
}

export function verifyJson(file: string): { ok: boolean; expected: string; actual: string } {
  const actual = sha256(readFileSync(file))
  const expected = readFileSync(`${file}.sha256`, "utf8").trim()
  return { ok: actual === expected, expected, actual }
}

/** One line per attempt, before and after each launch (the seed of 3.2's ledger). */
export function appendAttempt(runDir: string, row: Record<string, unknown>): void {
  appendFileSync(join(runDir, "attempts.jsonl"), `${JSON.stringify({ at: new Date().toISOString(), ...row })}\n`)
}
