cat > lib/pack.ts <<'EOF'
// Candidate identity is the artifact, not the branch (self-improve D9 §5).
// One commit is exported with `git archive`, built and packed INSIDE the
// sandbox (its build scripts are candidate code), and installed under the
// evaluator's store, which the candidate can never write.
import { cpSync, existsSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { sha256File } from "./hash"
import { CACHE_WRITABLE, CANDIDATES, TMP_WRITABLE } from "./paths"
import { toolVersions } from "./pin"
import { must, run } from "./proc"
import { candidateProfile, sandboxed, tempProfile } from "./sandbox"
import { writeJson } from "./result"

export interface CandidateInfo {
  id: string
  repo: string
  ref: string
  commit: string
  version: string
  tarball_sha256: string
  tarball: string
  install: string
  cli: string
  packed_at: string
  tools: Record<string, string>
}

export function candidateDir(id: string): string {
  return join(CANDIDATES, id)
}

export function readCandidate(id: string): CandidateInfo {
  const file = join(candidateDir(id), "candidate.json")
  if (!existsSync(file)) throw new Error(`no candidate ${id} (expected ${file})`)
  const info = JSON.parse(readFileSync(file, "utf8")) as CandidateInfo
  if (!existsSync(info.cli)) throw new Error(`candidate ${id} has no cli at ${info.cli}`)
  if (sha256File(info.tarball) !== info.tarball_sha256) throw new Error(`candidate ${id}: tarball hash moved`)
  return info
}

export async function packCandidate(o: { repo: string; ref: string; unreadable: string[]; log: (s: string) => void }): Promise<CandidateInfo> {
  const commit = (await must(["git", "rev-parse", `${o.ref}^{commit}`], { cwd: o.repo, timeoutMs: 30_000 }, "git rev-parse")).stdout.trim()
  const pointer = join(CANDIDATES, "by-commit", `${commit}.json`)
  if (existsSync(pointer)) {
    const { id } = JSON.parse(readFileSync(pointer, "utf8")) as { id: string }
    if (existsSync(join(candidateDir(id), "candidate.json"))) {
      o.log(`already packed: ${id} (commit ${commit.slice(0, 7)})`)
      return readCandidate(id)
    }
  }
  const work = mkdtempSync(join(tmpdir(), "evaluator-pack-"))
  const exportDir = join(work, "src")
  mkdirSync(exportDir)
  try {
    const tar = join(work, "src.tar")
    await must(["git", "archive", "--format=tar", "-o", tar, commit], { cwd: o.repo, timeoutMs: 120_000 }, "git archive")
    await must(["tar", "-xf", tar, "-C", exportDir], { cwd: work, timeoutMs: 120_000 }, "tar -x")
    const profile = tempProfile(candidateProfile({ writable: [work, ...CACHE_WRITABLE, ...TMP_WRITABLE], unreadable: o.unreadable }))
    o.log(`npm ci in ${exportDir} (sandboxed)`)
    await must(sandboxed(profile, ["npm", "ci", "--no-audit", "--no-fund"]), { cwd: exportDir, timeoutMs: 900_000 }, "npm ci")
    const dest = join(work, "pack")
    mkdirSync(dest)
    o.log("npm pack -w sofar.sh (sandboxed; prepack builds)")
    await must(sandboxed(profile, ["npm", "pack", "-w", "sofar.sh", "--pack-destination", dest]), { cwd: exportDir, timeoutMs: 900_000 }, "npm pack")
    const tgzName = readdirSync(dest).find((f) => f.endsWith(".tgz"))
    if (!tgzName) throw new Error("npm pack produced no tarball")
    const hash = sha256File(join(dest, tgzName))
    const id = `cand-${hash.slice(0, 12)}`
    const install = candidateDir(id)
    if (existsSync(join(install, "candidate.json"))) {
      o.log(`already packed under ${id}`)
      return readCandidate(id)
    }
    rmSync(install, { recursive: true, force: true })
    mkdirSync(install, { recursive: true })
    const tarball = join(install, "sofar.sh.tgz")
    cpSync(join(dest, tgzName), tarball)
    const installProfile = tempProfile(candidateProfile({ writable: [install, ...CACHE_WRITABLE, ...TMP_WRITABLE], unreadable: o.unreadable }))
    o.log(`npm install into ${install} (sandboxed)`)
    await must(sandboxed(installProfile, ["npm", "install", "--prefix", install, tarball, "--no-audit", "--no-fund"]), { cwd: install, timeoutMs: 600_000 }, "npm install")
    const cli = join(install, "node_modules", "sofar.sh", "dist", "cli.js")
    if (!existsSync(cli)) throw new Error(`install produced no cli at ${cli}`)
    const version = (await run(sandboxed(installProfile, ["node", cli, "--version"]), { cwd: install, timeoutMs: 60_000 })).stdout.trim()
    const info: CandidateInfo = { id, repo: o.repo, ref: o.ref, commit, version, tarball_sha256: hash, tarball, install, cli, packed_at: new Date().toISOString(), tools: await toolVersions() }
    writeJson(join(install, "candidate.json"), info)
    writeJson(pointer, { id, commit })
    return info
  } finally {
    rmSync(work, { recursive: true, force: true })
  }
}
