cat > lib/controls.ts <<'EOF'
// Controls prove the evaluator can see pass AND fail (self-improve D9 §6):
// the pinned hidden tests must pass on the chain-A reference and fail on the
// skeleton, per pin and per session, before any candidate is scored.
import { existsSync, mkdirSync, readFileSync } from "node:fs"
import { join } from "node:path"
import { CACHE_WRITABLE, CONTROLS, HIDDEN_TESTS, REFERENCE_A, REFERENCE_A_REF, SKELETON, SKELETON_REF, TMP_WRITABLE } from "./paths"
import { must } from "./proc"
import { writeJson } from "./result"
import { sandboxed, scoreProfile, writeProfile } from "./sandbox"
import { type Verdict, scoreRepo } from "./score"

export type SessionControl = { pass: number; fail: number } | "build_failed"

export interface ControlsRecord {
  pin_hash: string
  updated_at: string
  reference: { ref: string; clone: string }
  skeleton: { ref: string; clone: string }
  sessions: Record<string, { reference: SessionControl; skeleton: SessionControl }>
  last_verdicts: { reference: Verdict; skeleton: Verdict }
}

/** Do the recorded controls hold for these sessions? Pure. */
export function controlsHold(rec: ControlsRecord | null, sessions: string[]): { ok: boolean; why?: string } {
  if (!rec) return { ok: false, why: "no controls recorded for this pin" }
  for (const s of sessions) {
    const c = rec.sessions[s]
    if (!c) return { ok: false, why: `no control for ${s}` }
    if (c.reference === "build_failed" || c.reference.pass === 0 || c.reference.fail > 0) return { ok: false, why: `reference does not pass ${s}: ${JSON.stringify(c.reference)}` }
    if (c.skeleton !== "build_failed" && c.skeleton.fail === 0) return { ok: false, why: `skeleton does not fail ${s}: ${JSON.stringify(c.skeleton)}` }
  }
  return { ok: true }
}

export function controlsFile(pinHash: string): string {
  return join(CONTROLS, pinHash, "controls.json")
}

export function readControls(pinHash: string): ControlsRecord | null {
  const f = controlsFile(pinHash)
  return existsSync(f) ? (JSON.parse(readFileSync(f, "utf8")) as ControlsRecord) : null
}

async function cloneAt(src: string, ref: string, dest: string): Promise<void> {
  if (existsSync(join(dest, ".git"))) return
  await must(["git", "clone", "--no-hardlinks", "-q", src, dest], { cwd: CONTROLS, timeoutMs: 300_000 }, "git clone")
  await must(["git", "checkout", "-q", "--detach", ref], { cwd: dest, timeoutMs: 60_000 }, "git checkout")
}

function perSession(v: Verdict, sessions: string[]): Record<string, SessionControl> {
  const out: Record<string, SessionControl> = {}
  for (const s of sessions) {
    if (v.kind === "ok") out[s] = v.bySession[s] ?? { pass: 0, fail: 0 }
    else if (v.kind === "no_tests_ran" && v.detail === "build failed") out[s] = "build_failed"
    else out[s] = { pass: 0, fail: 0 }
  }
  return out
}

/** Run (or extend) the controls for this pin so that `sessions` are covered. */
export async function ensureControls(o: { pinHash: string; sessions: string[]; log: (s: string) => void }): Promise<ControlsRecord> {
  const existing = readControls(o.pinHash)
  if (controlsHold(existing, o.sessions).ok) return existing as ControlsRecord
  const dir = join(CONTROLS, o.pinHash)
  mkdirSync(dir, { recursive: true })
  const reference = join(dir, "reference")
  const skeleton = join(dir, "skeleton")
  o.log(`controls for pin ${o.pinHash.slice(0, 12)}: cloning reference@${REFERENCE_A_REF} and skeleton@${SKELETON_REF}`)
  await cloneAt(REFERENCE_A, REFERENCE_A_REF, reference)
  await cloneAt(SKELETON, SKELETON_REF, skeleton)
  const score = async (repo: string, name: string) => {
    const logDir = join(dir, `${name}-logs`)
    mkdirSync(logDir, { recursive: true })
    const profile = writeProfile(dir, `${name}.sb`, scoreProfile({ writable: [repo, ...CACHE_WRITABLE, ...TMP_WRITABLE] }))
    o.log(`scoring ${name} on ${o.sessions.join(",")} (sandboxed build + hidden tests)`)
    return scoreRepo({ repo, sessions: o.sessions, hiddenTests: HIDDEN_TESTS, profileFile: profile, logDir })
  }
  const ref = await score(reference, "reference")
  const skel = await score(skeleton, "skeleton")
  const sessions = { ...(existing?.sessions ?? {}) }
  const refPer = perSession(ref.verdict, o.sessions)
  const skelPer = perSession(skel.verdict, o.sessions)
  for (const s of o.sessions) sessions[s] = { reference: refPer[s] as SessionControl, skeleton: skelPer[s] as SessionControl }
  const rec: ControlsRecord = {
    pin_hash: o.pinHash,
    updated_at: new Date().toISOString(),
    reference: { ref: REFERENCE_A_REF, clone: reference },
    skeleton: { ref: SKELETON_REF, clone: skeleton },
    sessions,
    last_verdicts: { reference: ref.verdict, skeleton: skel.verdict },
  }
  writeJson(controlsFile(o.pinHash), rec)
  return rec
}

export { sandboxed }
