import { describe, expect, test } from "bun:test"
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { listFiles, manifestOf } from "../lib/hash"
import { diffManifest } from "../lib/pin"

function tree(): string {
  const d = mkdtempSync(join(tmpdir(), "evaluator-pin-"))
  mkdirSync(join(d, "hidden-tests", "vendor"), { recursive: true })
  mkdirSync(join(d, "hidden-tests", "node_modules", "x"), { recursive: true })
  writeFileSync(join(d, "hidden-tests", "s1.test.ts"), "test one")
  writeFileSync(join(d, "hidden-tests", "vendor", "fixture.ts"), "fixture")
  writeFileSync(join(d, "hidden-tests", "node_modules", "x", "index.js"), "dep")
  writeFileSync(join(d, "CHAIN-A.md"), "chain")
  return d
}

describe("pin manifest (tamper fixtures, audit S4)", () => {
  test("an unchanged tree verifies with no problems, node_modules excluded", () => {
    const d = tree()
    const files = listFiles(d)
    expect(files).toEqual(["CHAIN-A.md", "hidden-tests/s1.test.ts", "hidden-tests/vendor/fixture.ts"])
    expect(diffManifest(manifestOf(d, files), manifestOf(d, listFiles(d)))).toEqual([])
    rmSync(d, { recursive: true })
  })
  test("a modified hidden test is named", () => {
    const d = tree()
    const before = manifestOf(d, listFiles(d))
    writeFileSync(join(d, "hidden-tests", "s1.test.ts"), "test one, weakened")
    expect(diffManifest(before, manifestOf(d, listFiles(d)))).toEqual([{ kind: "modified", path: "hidden-tests/s1.test.ts" }])
    rmSync(d, { recursive: true })
  })
  test("an altered fixture is named", () => {
    const d = tree()
    const before = manifestOf(d, listFiles(d))
    writeFileSync(join(d, "hidden-tests", "vendor", "fixture.ts"), "fixture, altered")
    expect(diffManifest(before, manifestOf(d, listFiles(d)))).toEqual([{ kind: "modified", path: "hidden-tests/vendor/fixture.ts" }])
    rmSync(d, { recursive: true })
  })
  test("a missing test and an added file are both named", () => {
    const d = tree()
    const before = manifestOf(d, listFiles(d))
    rmSync(join(d, "hidden-tests", "s1.test.ts"))
    writeFileSync(join(d, "hidden-tests", "s1.helper.ts"), "shadow")
    expect(diffManifest(before, manifestOf(d, listFiles(d)))).toEqual([
      { kind: "missing", path: "hidden-tests/s1.test.ts" },
