    const results = await selfTest(profile, [
      { name: "write repo", cmd: `echo x > ${f.cell}/built.txt`, expect: "allow", leaves: `${f.cell}/built.txt` },
      { name: "write protected", cmd: `echo x > ${f.protectedDir}/forged.xml`, expect: "deny", leaves: `${f.protectedDir}/forged.xml` },
