#!/usr/bin/env bun
// sofar-evaluator — the frozen evaluator of the self-improve loop (self-improve 3.1, D9).
//
//   bun evaluator.ts pin write | pin check
//   bun evaluator.ts selftest
//   bun evaluator.ts pack --repo ~/IO/sofar --ref <commit>
//   bun evaluator.ts controls --sessions [redacted]
//   bun evaluator.ts run --candidate cand-xxxx --sessions [redacted] [--arm claude-sofar] [--reps 1] [--model opus] [--effort high] [--timeout-min 60] [--run <name>] [--dry-run] [--allow-dirty-evaluator]
//   bun evaluator.ts verify <result.json>
//
// Exit codes: 0 ok · 1 crash · 2 refusal (pin, sandbox self-test, controls, dirty evaluator) · 3 billing/limit stop (bench-refresh D14)
import { existsSync, mkdirSync, mkdtempSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { parseArgs } from "node:util"
import { controlsHold, ensureControls, readControls } from "./lib/controls"
import { sha256, sha256File } from "./lib/hash"
import { packCandidate, readCandidate } from "./lib/pack"
import {
  CACHE_WRITABLE,
  CANDIDATES,
  CLAUDE_CONFIG,
  CONTROLS,
  EVALUATOR_REPO,
  HANDOFF_BENCH,
  HIDDEN_TESTS,
  REFERENCE_A,
  RUNNER_LIB,
  RUNS,
  SANDBOX_EXEC,
  SCENARIO,
  SEALED,
  SOFAR_STATE,
  TMP_WRITABLE,
} from "./lib/paths"
import { type Pin, buildPin, describeProblem, pinHash, readPin, verifyPin, writePin } from "./lib/pin"
import { run } from "./lib/proc"
import { appendAttempt, verifyJson, writeJson } from "./lib/result"
import { candidateProfile, evaluatorProfile, scoreProfile, selfTest, standardProbes, tempProfile, writeProfile } from "./lib/sandbox"
import { scoreRepo } from "./lib/score"
import { writeShims } from "./lib/shims"

class Refusal extends Error {
  constructor(
    readonly reason: string,
    readonly details: unknown,
  ) {
    super(reason)
  }
}

const log = (s: string) => console.log(`[evaluator] ${s}`)

// D9 §9: the evaluator itself can never read the release holdout.
if (process.platform === "darwin" && !process.env.EVALUATOR_SANDBOXED) {
  const profile = tempProfile(evaluatorProfile({ unreadable: [SEALED] }))
  const child = Bun.spawn([SANDBOX_EXEC, "-f", profile, process.execPath, import.meta.path, ...process.argv.slice(2)], {
    env: { ...process.env, EVALUATOR_SANDBOXED: "1" },
    stdin: "inherit",
    stdout: "inherit",
    stderr: "inherit",
  })
  process.exit(await child.exited)
}

const { positionals, values } = parseArgs({
  allowPositionals: true,
  options: {
    repo: { type: "string" },
    ref: { type: "string", default: "HEAD" },
    candidate: { type: "string" },
    sessions: { type: "string" },
    arm: { type: "string", default: "claude-sofar" },
    reps: { type: "string", default: "1" },
    model: { type: "string", default: "opus" },
    effort: { type: "string", default: "high" },
    "timeout-min": { type: "string", default: "60" },
    run: { type: "string" },
    "dry-run": { type: "boolean", default: false },
    "allow-dirty-evaluator": { type: "boolean", default: false },
  },
})

const SEALED_FOR_CANDIDATE = () => [HIDDEN_TESTS, SEALED, REFERENCE_A, SCENARIO, EVALUATOR_REPO, CONTROLS]

async function git(cwd: string, ...args: string[]): Promise<string> {
  const r = await run(["git", ...args], { cwd, timeoutMs: 60_000 })
  return r.code === 0 ? r.stdout.trim() : ""
}

async function evaluatorIdentity(): Promise<{ commit: string; dirty: string[] }> {
  const commit = await git(EVALUATOR_REPO, "rev-parse", "HEAD")
  const dirty = (await git(EVALUATOR_REPO, "status", "--porcelain")).split("\n").filter(Boolean)
  return { commit, dirty }
}

async function requirePin(): Promise<{ pin: Pin; hash: string; head: string }> {
  const pin = readPin()
  const problems = await verifyPin(pin)
  if (problems.length) throw new Refusal("pin does not hold", problems.map(describeProblem))
  const head = await git(HANDOFF_BENCH, "rev-parse", "HEAD")
  if (head !== pin.handoff_bench_commit) log(`note: handoff-bench HEAD ${head.slice(0, 7)} differs from the pinned ${pin.handoff_bench_commit.slice(0, 7)}; every pinned file still matches by content`)
  return { pin, hash: pinHash(pin), head }
}

function sessionsArg(): string[] {
  if (!values.sessions) throw new Error("--sessions [redacted] is required")
  const list = values.sessions.split(",").map((s) => s.trim().toUpperCase())
  for (const s of list) if (!/^S\d+$/.test(s)) throw new Error(`bad session id ${s}`)
  return list
}

async function cmdPin(): Promise<number> {
  const sub = positionals[1]
  if (sub === "write") {
    const pin = await buildPin()
    writePin(pin)
    log(`pinned ${Object.keys(pin.files).length} files, handoff-bench ${pin.handoff_bench_commit.slice(0, 7)}, skeleton tree ${pin.skeleton.tree.slice(0, 7)}, reference tree ${pin.reference_a.tree.slice(0, 7)}`)
    log(`pin hash ${pinHash(pin)}`)
    return 0
  }
  if (sub === "check") {
    const pin = readPin()
    const problems = await verifyPin(pin)
    for (const p of problems) console.log(`  ✗ ${describeProblem(p)}`)
    if (problems.length) {
      log(`pin ${pinHash(pin).slice(0, 12)} does NOT hold (${problems.length} problem${problems.length === 1 ? "" : "s"})`)
      return 2
    }
    log(`pin ${pinHash(pin)} holds`)
    return 0
  }
  throw new Error("usage: pin write | pin check")
}

async function cmdSelftest(): Promise<number> {
  const dir = mkdtempSync(join(tmpdir(), "evaluator-selftest-"))
  const cell = join(dir, "cell")
  const results = join(dir, "results")
  mkdirSync(cell)
  mkdirSync(results)
  const profile = writeProfile(dir, "candidate.sb", candidateProfile({ writable: [cell, CLAUDE_CONFIG, SOFAR_STATE, ...TMP_WRITABLE, ...CACHE_WRITABLE], unreadable: [...SEALED_FOR_CANDIDATE(), results] }))
  const probes = standardProbes({ hiddenTests: HIDDEN_TESTS, sealed: SEALED, reference: REFERENCE_A, results, evaluatorRepo: EVALUATOR_REPO, runnerLib: RUNNER_LIB, cell })
  const out = await selfTest(profile, probes)
  for (const r of out) console.log(`  ${r.ok ? "✓" : "✗"} ${r.name} (${r.expect}) ${r.ok ? "" : r.detail}`)
  const bad = out.filter((r) => !r.ok)
  log(bad.length ? `${bad.length} probe(s) FAILED — the boundary does not hold on this machine` : `all ${out.length} probes hold`)
  return bad.length ? 2 : 0
}

async function cmdPack(): Promise<number> {
  if (!values.repo) throw new Error("--repo <sofar clone> is required")
  const info = await packCandidate({ repo: values.repo, ref: values.ref ?? "HEAD", unreadable: SEALED_FOR_CANDIDATE(), log })
  console.log(JSON.stringify(info, null, 2))
  return 0
}

async function cmdControls(): Promise<number> {
  const { hash } = await requirePin()
  const sessions = sessionsArg()
  const rec = await ensureControls({ pinHash: hash, sessions, log })
  const hold = controlsHold(rec, sessions)
  for (const s of sessions) console.log(`  ${s}: reference ${JSON.stringify(rec.sessions[s]?.reference)} · skeleton ${JSON.stringify(rec.sessions[s]?.skeleton)}`)
  log(hold.ok ? `controls hold for pin ${hash.slice(0, 12)}` : `controls do NOT hold: ${hold.why}`)
  return hold.ok ? 0 : 2
}

interface RunnerLib {
  setupCell(paths: { dir: string; repo: string; artifacts: string }, arm: any): Promise<void>
  composePrompt(chain: any, sessionId: string, arm: any, cellDir: string, repo: string): string
  launch(arm: any, paths: any, prompt: string, cfg: any): Promise<any>
  commitSession(repo: string, sessionId: string): Promise<void>
  ARMS: Record<string, any>
  loadChain(id: "A" | "B"): any
  BillingStop: new (...a: any[]) => Error
}

/** Import the PINNED runner modules — only after the pin held and the environment was set. */
async function loadRunner(): Promise<RunnerLib> {
  const cell = await import(join(RUNNER_LIB, "cell.ts"))
  const arms = await import(join(RUNNER_LIB, "arms.ts"))
  const chain = await import(join(RUNNER_LIB, "chain.ts"))
  const billing = await import(join(RUNNER_LIB, "billing.ts"))
  return { setupCell: cell.setupCell, composePrompt: cell.composePrompt, launch: cell.launch, commitSession: cell.commitSession, ARMS: arms.ARMS, loadChain: chain.loadChain, BillingStop: billing.BillingStop }
}

async function cmdRun(): Promise<number> {
  const startedAt = new Date().toISOString()
  const { pin, hash: pinH, head } = await requirePin()
  const evaluator = await evaluatorIdentity()
  if (evaluator.dirty.length && !values["allow-dirty-evaluator"]) throw new Refusal("evaluator working tree is dirty; commit it or pass --allow-dirty-evaluator (recorded)", evaluator.dirty)
  if (!values.candidate) throw new Error("--candidate <id> is required")
  const cand = readCandidate(values.candidate)
  const sessions = sessionsArg()
  const reps = Number(values.reps)
  const controls = await ensureControls({ pinHash: pinH, sessions, log })
  const hold = controlsHold(controls, sessions)
  if (!hold.ok) throw new Refusal(`controls do not hold: ${hold.why}`, controls.sessions)

  const runId = values.run ?? `${cand.id}-${startedAt.replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z")}`
  const runDir = join(RUNS, runId)
  if (existsSync(runDir)) throw new Refusal(`run ${runId} already exists`, runDir)
  const cellsDir = join(runDir, "cells")
  const resultsDir = join(runDir, "results")
  const sandboxDir = join(runDir, "sandbox")
  for (const d of [cellsDir, resultsDir, sandboxDir]) mkdirSync(d, { recursive: true })

  const profileText = candidateProfile({ writable: [cellsDir, CLAUDE_CONFIG, SOFAR_STATE, ...TMP_WRITABLE, ...CACHE_WRITABLE], unreadable: [...SEALED_FOR_CANDIDATE(), resultsDir] })
  const profile = writeProfile(sandboxDir, "candidate.sb", profileText)
  const probes = standardProbes({ hiddenTests: HIDDEN_TESTS, sealed: SEALED, reference: REFERENCE_A, results: resultsDir, evaluatorRepo: EVALUATOR_REPO, runnerLib: RUNNER_LIB, candidateDir: cand.install, cell: cellsDir })
  const probeResults = await selfTest(profile, probes)
  writeJson(join(resultsDir, "selftest.json"), probeResults)
  const badProbes = probeResults.filter((r) => !r.ok)
  if (badProbes.length) throw new Refusal("sandbox self-test failed; nothing launched", badProbes)
  log(`sandbox self-test: all ${probeResults.length} probes hold`)

  const claudeBin = Bun.which("claude")
  const nodeBin = Bun.which("node")
  if (!claudeBin || !nodeBin) throw new Error("claude or node not on PATH")
  const shims = writeShims(join(runDir, "shims"), { profileFile: profile, claudeBin, nodeBin, candidateCli: cand.cli })
  process.env.BENCH_SOFAR_PREFIX = shims.prefixDir
  process.env.PATH = `${shims.binDir}:${process.env.PATH ?? ""}`
  const runner = await loadRunner()
  const arm = runner.ARMS[values.arm ?? "claude-sofar"]
  if (!arm) throw new Error(`unknown arm ${values.arm}`)
  if (arm.agent !== "claude-code") throw new Refusal(`arm ${arm.id} runs ${arm.agent}; only claude-code has a sandbox shim today`, arm.id)
  if (arm.mode && arm.mode !== "sessions") throw new Refusal(`arm ${arm.id} is mode ${arm.mode}; only per-session [redacted] are supported today`, arm.id)
  const chain = runner.loadChain("A")
  const cfg = { models: { "claude-code": values.model }, efforts: { "claude-code": values.effort }, sessionTimeoutMs: Number(values["timeout-min"]) * 60_000 }
  const base = {
    evaluator: { repo: EVALUATOR_REPO, commit: evaluator.commit, dirty: evaluator.dirty },
    pin_hash: pinH,
    pinned_handoff_bench: pin.handoff_bench_commit,
    handoff_bench_head_at_run: head,
    candidate: { id: cand.id, commit: cand.commit, version: cand.version, tarball_sha256: cand.tarball_sha256, repo: cand.repo, ref: cand.ref },
    controls: { file: join(CONTROLS, pinH, "controls.json"), updated_at: controls.updated_at },
    sandbox: { profile_sha256: sha256(profileText), shims: shims.files.map((f) => ({ file: f, sha256: sha256File(f) })) },
    run: runId,
    arm: arm.id,
    model: values.model,
    effort: values.effort,
    tools: pin.tools,
  }
  writeJson(join(resultsDir, "run.json"), { ...base, sessions, reps, dry_run: values["dry-run"], started_at: startedAt })
  log(`run ${runId}: candidate ${cand.id} (${cand.version} @ ${cand.commit.slice(0, 7)}), arm ${arm.id}, sessions ${sessions.join(",")}, reps ${reps}${values["dry-run"] ? ", DRY RUN (no agent launch)" : ""}`)

  for (let rep = 1; rep <= reps; rep++) {
    const dir = join(cellsDir, arm.id, `r${rep}`)
    const paths = { dir, repo: join(dir, "repo"), artifacts: join(dir, "artifacts") }
    mkdirSync(paths.artifacts, { recursive: true })
    log(`cell ${arm.id}/r${rep}: clone skeleton + arm setup (candidate sofar init through the shim)`)
    await runner.setupCell(paths, arm)
    for (let i = 0; i < sessions.length; i++) {
      const s = sessions[i] as string
      const prompt = runner.composePrompt(chain, s, arm, paths.dir, paths.repo)
      const tag = `${arm.id}-r${rep}-${s}`
      if (values["dry-run"]) {
        log(`  ${s}: prompt composed (${prompt.length} chars, sha256 ${sha256(prompt).slice(0, 12)}); dry run, not launched`)
        continue
      }
      appendAttempt(resultsDir, { phase: "launch", run: runId, arm: arm.id, rep, session: s, candidate: cand.id, model: values.model, effort: values.effort })
      const t0 = new Date().toISOString()
      let outcome: any
      try {
        outcome = await runner.launch(arm, paths, prompt, cfg)
      } catch (err) {
        if (err instanceof runner.BillingStop) {
          appendAttempt(resultsDir, { phase: "billing_stop", run: runId, arm: arm.id, rep, session: s, evidence: String(err.message).slice(0, 500) })
          writeJson(join(resultsDir, "stop.json"), { reason: "billing_stop", at: new Date().toISOString(), evidence: String(err.message).slice(0, 2000) })
          log(`BILLING/LIMIT STOP (bench-refresh D14): ${err.message}`)
          return 3
        }
        throw err
      }
      appendAttempt(resultsDir, { phase: "launched", run: runId, arm: arm.id, rep, session: s, ok: outcome.ok, timedOut: outcome.timedOut, exit: outcome.exitCode, ms: outcome.ms, turns: outcome.turns, usage: outcome.usage })
      const logDir = join(resultsDir, tag)
      mkdirSync(logDir, { recursive: true })
