async function cmdVerify(): Promise<number> {
  const file = positionals[1]
  if (!file) throw new Error("usage: verify <result.json>")
  const v = verifyJson(file)
  log(v.ok ? `${file}: intact (${v.actual.slice(0, 12)})` : `${file}: MODIFIED — recorded ${v.expected.slice(0, 12)}, found ${v.actual.slice(0, 12)}`)
  return v.ok ? 0 : 2
}

async function main(): Promise<number> {
  switch (positionals[0]) {
    case "pin":
      return cmdPin()
    case "selftest":
      return cmdSelftest()
    case "pack":
      return cmdPack()
    case "controls":
      return cmdControls()
    case "run":
      return cmdRun()
    case "verify":
      return cmdVerify()
    default:
      console.log("usage: evaluator pin write|check | selftest | pack --repo <r> --ref <ref> | controls --sessions [redacted] | run --candidate <id> --sessions [redacted] [...] | verify <result.json>")
      return 1
  }
}

