// The durable spend ledger (self-improve 3.2, D12): one append-only JSONL across
// every run, written only by the evaluator. Every attempt costs something —
// reported, or estimated when unknown or never closed — and every cap check
// reads this file plus the round-1 ledgers, so one number means the same thing
// in both tools (bench-refresh D17).
import { appendFileSync, existsSync, mkdirSync, readdirSync, readFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { EVAL_ROOT, HOME } from "./paths"

export const LEDGER_FILE = join(EVAL_ROOT, "ledger.jsonl")
/** The round-1 runner's cell root; its per-round ledger.json files are read, never written. */
export const ROUND_CELLS_ROOT = join(HOME, "IO", "bench-cells", "boopada")

export type RowKind = "pack" | "controls" | "score" | "launch_intent" | "launch_outcome" | "launch_lost" | "refusal" | "stop"

export interface LedgerRow {
  id: string
  at: string
  kind: RowKind
  run?: string
  candidate?: string
  arm?: string
  rep?: number
  session?: string
  model?: string
  /** For launch_outcome / launch_lost: the intent row this closes. */
  intent?: string
  ok?: boolean
  timed_out?: boolean
  exit?: number | null
  ms?: number
  turns?: number | null
  tokens?: { input: number; cache_creation: number; cache_read: number; output: number } | null
  /** Reported by the agent (API-equivalent on a subscription); null when it reported none. */
  cost_usd?: number | null
  reason?: string
  detail?: unknown
}

export function appendRow(row: Omit<LedgerRow, "id" | "at">, file: string = LEDGER_FILE): LedgerRow {
  const full: LedgerRow = { id: crypto.randomUUID(), at: new Date().toISOString(), ...row }
  mkdirSync(dirname(file), { recursive: true })
  appendFileSync(file, `${JSON.stringify(full)}\n`)
  return full
}

export function readRows(file: string = LEDGER_FILE): LedgerRow[] {
  if (!existsSync(file)) return []
  const rows: LedgerRow[] = []
  for (const line of readFileSync(file, "utf8").split("\n")) {
    if (!line.trim()) continue
    try {
      rows.push(JSON.parse(line) as LedgerRow)
    } catch {
      // a torn last line from a crash mid-write is skipped, never fatal
    }
  }
  return rows
}

export interface Attempt {
  intent: LedgerRow
  outcome?: LedgerRow
  lost?: LedgerRow
  status: "reported" | "unknown" | "open" | "lost"
  /** What this attempt is charged in a cap check. */
  charged_usd: number
}

/** Pair intents with what closed them. Pure. */
export function attempts(rows: LedgerRow[], estimateUsd: number): Attempt[] {
  const byIntent = new Map<string, Attempt>()
  for (const r of rows) if (r.kind === "launch_intent") byIntent.set(r.id, { intent: r, status: "open", charged_usd: estimateUsd })
  for (const r of rows) {
    if (!r.intent) continue
    const a = byIntent.get(r.intent)
    if (!a) continue
    if (r.kind === "launch_outcome") {
      a.outcome = r
      if (typeof r.cost_usd === "number") {
        a.status = "reported"
        a.charged_usd = r.cost_usd
      } else {
        a.status = "unknown"
        a.charged_usd = estimateUsd
      }
    } else if (r.kind === "launch_lost") {
      a.lost = r
      a.status = "lost"
      a.charged_usd = estimateUsd
    }
  }
  return [...byIntent.values()]
}

export interface Spend {
  attempts: number
  reported_usd: number
  reported_n: number
  unknown_n: number
  open_n: number
  lost_n: number
  /** reported + (unknown + open + lost) × estimate. */
  charged_usd: number
}

export function spend(list: Attempt[], filter: { run?: string; sinceMs?: number } = {}): Spend {
  const s: Spend = { attempts: 0, reported_usd: 0, reported_n: 0, unknown_n: 0, open_n: 0, lost_n: 0, charged_usd: 0 }
  for (const a of list) {
    if (filter.run && a.intent.run !== filter.run) continue
    const endedAt = a.outcome?.at ?? a.lost?.at ?? a.intent.at
    if (filter.sinceMs !== undefined && Date.parse(endedAt) < filter.sinceMs) continue
    s.attempts++
    s.charged_usd += a.charged_usd
    if (a.status === "reported") {
      s.reported_n++
      s.reported_usd += a.charged_usd
    } else if (a.status === "unknown") s.unknown_n++
    else if (a.status === "open") s.open_n++
    else s.lost_n++
  }
  return s
}

/** The round-1 runner's Claude spend, computed exactly as its budget.ts does (claude-* arms, reported cost, ended in the window). */
export function roundClaudeSpend(sinceMs: number, root: string = ROUND_CELLS_ROOT): number {
  if (!existsSync(root)) return 0
  let total = 0
  for (const round of readdirSync(root)) {
    const file = join(root, round, "ledger.json")
    if (!existsSync(file)) continue
    let ledger: any
    try {
      ledger = JSON.parse(readFileSync(file, "utf8"))
    } catch {
      continue
    }
    for (const cell of Object.values(ledger.cells ?? {}) as any[]) {
      if (!String(cell.arm ?? "").startsWith("claude-")) continue
      for (const s of Object.values(cell.sessions ?? {}) as any[]) {
        const cost = s?.usage?.reported_cost_usd
        if (cost && s.endedAt && Date.parse(s.endedAt) >= sinceMs) total += cost
      }
    }
  }
  return total
}

export interface Caps {
  runMaxUsd: number
  weekUsd: number
  windowUsd: number
  nextSessionUsd: number
  maxLaunches: number
}

export interface CapCheck {
  ok: boolean
  reason?: string
  run: Spend
  week_evaluator_usd: number
  week_round_usd: number
  window_evaluator_usd: number
  window_round_usd: number
}

/** May one more launch happen for `run`? Pure over the rows and the round spend numbers. */
export function capCheck(rows: LedgerRow[], run: string, caps: Caps, round: { weekUsd: number; windowUsd: number }, now = Date.now()): CapCheck {
  const list = attempts(rows, caps.nextSessionUsd)
  const runSpend = spend(list, { run })
  const week = spend(list, { sinceMs: now - 7 * 86_400_000 })
  const window = spend(list, { sinceMs: now - 5 * 3_600_000 })
  const base = { run: runSpend, week_evaluator_usd: week.charged_usd, week_round_usd: round.weekUsd, window_evaluator_usd: window.charged_usd, window_round_usd: round.windowUsd }
  const f = (n: number) => `$${n.toFixed(2)}`
  if (runSpend.attempts >= caps.maxLaunches) return { ok: false, reason: `run ${run} has ${runSpend.attempts} launches (reported ${runSpend.reported_n}, unknown ${runSpend.unknown_n}, open ${runSpend.open_n}, lost ${runSpend.lost_n}) against --max-launches ${caps.maxLaunches}`, ...base }
  if (runSpend.charged_usd + caps.nextSessionUsd > caps.runMaxUsd) return { ok: false, reason: `run ${run} charged ${f(runSpend.charged_usd)} (${f(runSpend.reported_usd)} reported + ${runSpend.unknown_n + runSpend.open_n + runSpend.lost_n} × ${f(caps.nextSessionUsd)} estimated) + next ~${f(caps.nextSessionUsd)} would pass --max-usd ${f(caps.runMaxUsd)}`, ...base }
  const weekTotal = week.charged_usd + round.weekUsd
  if (weekTotal + caps.nextSessionUsd > caps.weekUsd) return { ok: false, reason: `7-day Claude spend ${f(weekTotal)} (evaluator ${f(week.charged_usd)} + round ledgers ${f(round.weekUsd)}) + next ~${f(caps.nextSessionUsd)} would pass the ${f(caps.weekUsd)} cap (bench-refresh D17)`, ...base }
  const windowTotal = window.charged_usd + round.windowUsd
  if (windowTotal + caps.nextSessionUsd > caps.windowUsd) return { ok: false, reason: `5-hour Claude spend ${f(windowTotal)} (evaluator ${f(window.charged_usd)} + round ledgers ${f(round.windowUsd)}) + next ~${f(caps.nextSessionUsd)} would pass the ${f(caps.windowUsd)} cap (bench-refresh D17)`, ...base }
  return { ok: true, ...base }
}

/** Which (rep, session) slots of a run are done, open (intent without outcome) or pending. Pure. */
export function resumePlan(rows: LedgerRow[], run: string, slots: Array<{ rep: number; session: string }>, hasResult: (rep: number, session: string) => boolean): Array<{ rep: number; session: string; state: "done" | "open" | "pending"; openIntent?: LedgerRow }> {
  const list = attempts(rows, 0).filter((a) => a.intent.run === run)
  return slots.map((slot) => {
    if (hasResult(slot.rep, slot.session)) return { ...slot, state: "done" as const }
    const open = list.find((a) => a.status === "open" && a.intent.rep === slot.rep && a.intent.session === slot.session)
    return open ? { ...slot, state: "open" as const, openIntent: open.intent } : { ...slot, state: "pending" as const }
  })
}
