  process.env.BENCH_SOFAR_PREFIX = shims.prefixDir
  process.env.PATH = `${shims.binDir}:${process.env.PATH ?? ""}`
  const runner = await loadRunner(P.runnerLib)
  const arm = runner.ARMS[values.arm ?? "claude-sofar"]
  if (!arm) throw new Error(`unknown arm ${values.arm}`)
  if (arm.agent !== "claude-code") throw new Refusal(`arm ${arm.id} runs ${arm.agent}; only claude-code has a sandbox shim today`, arm.id)
  if (arm.mode && arm.mode !== "sessions") throw new Refusal(`arm ${arm.id} is mode ${arm.mode}; only per-session [redacted] are supported today`, arm.id)
  const chain = runner.loadChain("A")
  const cfg = { models: { "claude-code": values.model }, efforts: { "claude-code": values.effort }, sessionTimeoutMs: Number(values["timeout-min"]) * 60_000 }
  const budget = { ...caps(), maxLaunches: values["max-launches"] ? Number(values["max-launches"]) : sessions.length * reps }
  const base = {
    evaluator: { repo: EVALUATOR_REPO, commit: evaluator.commit, dirty: evaluator.dirty },
    pin_hash: pinH,
    pinned_handoff_bench: pin.handoff_bench_commit,
    snapshot: P.root,
    handoff_bench_head_at_run: head,
    candidate: { id: cand.id, commit: cand.commit, version: cand.version, tarball_sha256: cand.tarball_sha256, repo: cand.repo, ref: cand.ref },
    controls: { file: join(CONTROLS, pinH, "controls.json"), updated_at: controls.updated_at },
    sandbox: { profile_sha256: sha256(profileText), shims: shims.files.map((f) => ({ file: f, sha256: sha256File(f) })) },
    run: runId,
    arm: arm.id,
    model: values.model,
    effort: values.effort,
    budget,
    ledger: LEDGER_FILE,
    tools: pin.tools,
  }
  const runJson = (extra: Record<string, unknown>) => writeJson(join(resultsDir, "run.json"), { ...base, sessions, reps, dry_run: values["dry-run"], started_at: startedAt, ...extra })
  runJson({})
  log(`run ${runId}${resuming ? " (RESUMED)" : ""}: candidate ${cand.id} (${cand.version} @ ${cand.commit.slice(0, 7)}), arm ${arm.id}, sessions ${sessions.join(",")}, reps ${reps}${values["dry-run"] ? ", DRY RUN (no agent launch)" : ""}`)
  log(`budget: --max-usd $${budget.runMaxUsd}, --max-launches ${budget.maxLaunches}, rolling $${budget.weekUsd}/7d and $${budget.windowUsd}/5h over evaluator + round ledgers, unknown or lost attempts charged $${budget.nextSessionUsd} each (D12)`)

  const resultFile = (rep: number, s: string) => join(resultsDir, `${arm.id}-r${rep}-${s}.json`)
  const slots = Array.from({ length: reps }, (_, i) => sessions.map((s) => ({ rep: i + 1, session: s }))).flat()
  const plan = resumePlan(readRows(), runId, slots, (rep, s) => existsSync(resultFile(rep, s)))
  const doneSlots = plan.filter((p) => p.state === "done").length
  if (resuming) log(`resume: ${doneSlots} slot(s) done, ${plan.filter((p) => p.state === "open").length} open (lost), ${plan.filter((p) => p.state === "pending").length} pending`)
  const resetDone = new Set<number>()

  for (const slot of plan) {
    const { rep, session: s } = slot
    const i = sessions.indexOf(s)
    const dir = join(cellsDir, arm.id, `r${rep}`)
    const paths = { dir, repo: join(dir, "repo"), artifacts: join(dir, "artifacts") }
    if (slot.state === "done") {
      log(`  r${rep} ${s}: already scored, skipped`)
      continue
    }
    if (!existsSync(join(paths.repo, ".git"))) {
      mkdirSync(paths.artifacts, { recursive: true })
      log(`cell ${arm.id}/r${rep}: clone skeleton + arm setup (candidate sofar init through the shim)`)
      await runner.setupCell(paths, arm)
    } else if (slot.state === "open" && !resetDone.has(rep)) {
      await resetCell(paths.repo)
      resetDone.add(rep)
      log(`cell ${arm.id}/r${rep}: partial work of the lost attempt discarded (reset to the last bench commit)`)
    }
    if (slot.state === "open" && slot.openIntent) {
      appendRow({ kind: "launch_lost", intent: slot.openIntent.id, run: runId, arm: arm.id, rep, session: s, reason: "intent never closed; charged at the next-session [redacted] })
      appendAttempt(resultsDir, { phase: "lost", run: runId, arm: arm.id, rep, session: s, intent: slot.openIntent.id })
    }
    const prompt = runner.composePrompt(chain, s, arm, paths.dir, paths.repo)
    const tag = `${arm.id}-r${rep}-${s}`
    if (values["dry-run"]) {
      log(`  r${rep} ${s}: prompt composed (${prompt.length} chars, sha256 ${sha256(prompt).slice(0, 12)}); dry run, not launched`)
      continue
    }
    // D12 §3: every launch is preceded by a cap check over this ledger plus the round ledgers.
    const now = Date.now()
    const check = capCheck(readRows(), runId, budget, { weekUsd: roundClaudeSpend(now - 7 * 86_400_000), windowUsd: roundClaudeSpend(now - 5 * 3_600_000) }, now)
    log(`  r${rep} ${s}: run charged $${check.run.charged_usd.toFixed(2)} over ${check.run.attempts} attempt(s); 7d $${(check.week_evaluator_usd + check.week_round_usd).toFixed(2)} (evaluator $${check.week_evaluator_usd.toFixed(2)}), 5h $${(check.window_evaluator_usd + check.window_round_usd).toFixed(2)}`)
    if (!check.ok) {
      appendRow({ kind: "stop", run: runId, reason: "budget_pause", detail: check.reason })
      writeJson(join(resultsDir, `stop-${Date.now()}.json`), { reason: "budget_pause", at: new Date().toISOString(), detail: check.reason, check })
      log(`BUDGET PAUSE (D12): ${check.reason}. Resume with --resume once it fits, or raise the cap explicitly.`)
      runJson({ paused_at: new Date().toISOString(), pause: check.reason })
      return 4
    }
    const intent = appendRow({ kind: "launch_intent", run: runId, candidate: cand.id, arm: arm.id, rep, session: s, model: values.model })
    appendAttempt(resultsDir, { phase: "launch", run: runId, arm: arm.id, rep, session: s, candidate: cand.id, model: values.model, effort: values.effort, intent: intent.id })
    const t0 = new Date().toISOString()
    let outcome: any
    try {
      outcome = await runner.launch(arm, paths, prompt, cfg)
    } catch (err) {
      if (err instanceof runner.BillingStop) {
        appendRow({ kind: "launch_outcome", intent: intent.id, run: runId, arm: arm.id, rep, session: s, ok: false, cost_usd: null, reason: "billing_stop" })
        appendRow({ kind: "stop", run: runId, reason: "billing_stop", detail: String(err.message).slice(0, 500) })
        appendAttempt(resultsDir, { phase: "billing_stop", run: runId, arm: arm.id, rep, session: s, evidence: String(err.message).slice(0, 500) })
        writeJson(join(resultsDir, "stop.json"), { reason: "billing_stop", at: new Date().toISOString(), evidence: String(err.message).slice(0, 2000) })
        log(`BILLING/LIMIT STOP (bench-refresh D14): ${err.message}`)
        return 3
      }
      throw err
    }
    const u = outcome.usage
    appendRow({
      kind: "launch_outcome",
      intent: intent.id,
      run: runId,
      arm: arm.id,
      rep,
      session: s,
      ok: outcome.ok,
      timed_out: outcome.timedOut,
      exit: outcome.exitCode,
      ms: outcome.ms,
      turns: outcome.turns,
      tokens: u ? { input: u.input_tokens, cache_creation: u.cache_creation_tokens, cache_read: u.cache_read_tokens, output: u.output_tokens } : null,
      cost_usd: typeof u?.reported_cost_usd === "number" ? u.reported_cost_usd : null,
    })
    appendAttempt(resultsDir, { phase: "launched", run: runId, arm: arm.id, rep, session: s, intent: intent.id, ok: outcome.ok, timedOut: outcome.timedOut, exit: outcome.exitCode, ms: outcome.ms, turns: outcome.turns, usage: u })
    const logDir = join(resultsDir, tag)
    mkdirSync(logDir, { recursive: true })
    writeFileSync(join(logDir, "agent.stdout.json"), outcome.raw?.stdout ?? "")
    writeFileSync(join(logDir, "agent.stderr.txt"), outcome.raw?.stderr ?? "")
    await runner.commitSession(paths.repo, s)
    const scoreSb = writeProfile(sandboxDir, `score-${arm.id}-r${rep}.sb`, scoreProfile({ writable: [paths.repo, ...TMP_WRITABLE, ...CACHE_WRITABLE] }))
    log(`  r${rep} ${s}: agent ${outcome.ok ? "ok" : "FAILED"} in ${Math.round(outcome.ms / 1000)}s, ${outcome.turns ?? "?"} turns, cost ${u?.reported_cost_usd ?? "unknown"}; scoring (sandboxed build + hidden tests)`)
    const score = await scoreRepo({ repo: paths.repo, sessions: sessions.slice(0, i + 1), hiddenTests: P.hiddenTests, profileFile: scoreSb, logDir })
    appendRow({ kind: "score", run: runId, arm: arm.id, rep, session: s, ms: score.ms, detail: { build: score.build, verdict: score.verdict.kind } })
    const result = {
      ...base,
      rep,
      session: s,
      sessions_scored: sessions.slice(0, i + 1),
      prompt_sha256: sha256(prompt),
      intent: intent.id,
      started_at: t0,
      ended_at: new Date().toISOString(),
      agent: { ok: outcome.ok, timedOut: outcome.timedOut, exitCode: outcome.exitCode, ms: outcome.ms, turns: outcome.turns, sessionId: outcome.sessionId, usage: u },
      score: { build: score.build, verdict: score.verdict, ms: score.ms, profile_sha256: sha256File(scoreSb) },
    }
    const h = writeJson(resultFile(rep, s), result)
    const v = score.verdict
    log(`  r${rep} ${s}: build ${score.build}, ${v.kind === "ok" ? `tests ${v.pass} pass / ${v.fail} fail` : `${v.kind}: ${v.detail}`} → ${tag}.json (${h.slice(0, 12)})`)
  }
  const final = spend(attempts(readRows(), budget.nextSessionUsd), { run: runId })
  runJson({ ended_at: new Date().toISOString(), spend: final })
  log(`run ${runId} complete: ${final.attempts} attempt(s), reported $${final.reported_usd.toFixed(2)}, charged $${final.charged_usd.toFixed(2)} (${final.unknown_n} unknown, ${final.lost_n} lost)`)
  return 0
}

function cmdLedger(): number {
  const est = Number(values["next-session-usd"])
  const rows = readRows()
  const list = attempts(rows, est)
  const now = Date.now()
  const runs = [...new Set(list.map((a) => a.intent.run ?? "?"))].sort()
  const report = {
    file: LEDGER_FILE,
    rows: rows.length,
    kinds: rows.reduce<Record<string, number>>((m, r) => ((m[r.kind] = (m[r.kind] ?? 0) + 1), m), {}),
    estimate_usd: est,
    all: spend(list),
    rolling: {
      week: { evaluator: spend(list, { sinceMs: now - 7 * 86_400_000 }), round_usd: roundClaudeSpend(now - 7 * 86_400_000) },
      window: { evaluator: spend(list, { sinceMs: now - 5 * 3_600_000 }), round_usd: roundClaudeSpend(now - 5 * 3_600_000) },
    },
    runs: Object.fromEntries(runs.filter((r) => !values.run || r === values.run).map((r) => [r, spend(list, { run: r })])),
    time_ms: rows.reduce<Record<string, number>>((m, r) => ((m[r.kind] = (m[r.kind] ?? 0) + (r.ms ?? 0)), m), {}),
  }
  if (values.json) {
    console.log(JSON.stringify(report, null, 2))
    return 0
  }
  const f = (n: number) => `$${n.toFixed(2)}`
  const line = (name: string, s: ReturnType<typeof spend>) => console.log(`  ${name.padEnd(34)} ${String(s.attempts).padStart(3)} attempts  reported ${f(s.reported_usd).padStart(8)}  charged ${f(s.charged_usd).padStart(8)}  unknown ${s.unknown_n} open ${s.open_n} lost ${s.lost_n}`)
  console.log(`ledger ${LEDGER_FILE}: ${rows.length} rows (${Object.entries(report.kinds).map(([k, n]) => `${k} ${n}`).join(", ")}); unknown/open/lost charged ${f(est)} each`)
  line("all runs", report.all)
  for (const [r, s] of Object.entries(report.runs)) line(r, s)
  console.log(`  7-day Claude spend: evaluator ${f(report.rolling.week.evaluator.charged_usd)} + round ledgers ${f(report.rolling.week.round_usd)} = ${f(report.rolling.week.evaluator.charged_usd + report.rolling.week.round_usd)} (cap $${values["week-usd"]})`)
  console.log(`  5-hour Claude spend: evaluator ${f(report.rolling.window.evaluator.charged_usd)} + round ledgers ${f(report.rolling.window.round_usd)} = ${f(report.rolling.window.evaluator.charged_usd + report.rolling.window.round_usd)} (cap $${values["window-usd"]})`)
  console.log(`  time: ${Object.entries(report.time_ms).filter(([, ms]) => ms).map(([k, ms]) => `${k} ${Math.round(ms / 1000)}s`).join(", ")}`)
  return 0
}

